window.AUTH=window.AUTH||{};window.AUTH["89-1283"]={"d":"89-1283","id":"1990/89-1283","n":"Arcadia, Ohio v. Ohio Power Company","src":["osg"],"briefs":[{"k":"reply","label":"Reply brief for the Federal Energy Regulatory Commission /1/","date":"","url":"https://www.justice.gov/osg/media/232896/dl?inline","side":"pet","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/arcadia-ohio-et-al-petitioners-v-ohio-power-company-et-al-0","toa":false,"n":10},{"k":"united-states","label":"Brief for the Federal Energy Regulatory Commission as respondent supporting petitioners and for the Securities and Exchange Commission as amicus curiae","date":"","url":"https://www.justice.gov/osg/media/210591/dl?inline","side":"pet","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/arcadia-ohio-et-al-petitioners-v-ohio-power-company-et-al","toa":false,"n":47}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep498/usrep498073/usrep498073.pdf","tr":false,"items":[{"t":"case","label":"Court in Northwestern Electric Co. v. FPC","cite":"321 U.S. 119","y":1944,"id":"scdb/1943-061","sc":1,"op":1,"sum":"that the order was authorized by the Act and was constitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"","1":""}},{"t":"case","label":"Bowen v. Georgetown Univ. Hosp.","cite":"109 S. Ct. 468","y":1988,"id":"1988/87-1097","sc":1,"sum":"Under the Medicare program, the Government reimburses health care providers for expenses incurred in providing medical services to Medicare beneficiaries. The Medicare Act in 42 U. S. C. § 1395x(v)(1)(A) authorizes the Secretary of Health and Human Services (Secretary) to promulgate cost-reimbursement regulations and also provides that \"[s]uch regulations shall... (ii) provide for the making of suitable retroactive …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"FPC v. Texaco, Inc.","cite":"417 U.S. 380","y":1974,"id":"1973/72-1490","sc":1,"sum":"Following its notice of proposed rulemaking \"propos[ing] prospectively to exempt from regulation under the Natural Gas Act all existing and all future jurisdictional sales made by small producers...,\" and the filing of comments and informal conferences, the Federal Power Commission (FPC) issued Order No. 428, which exempted all existing and future sales by \"small producers\" from direct rate regulation, and provided …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Investment Co. Inst. v. Camp","cite":"401 U.S. 617","y":1971,"id":"1970/61","sc":1,"sum":"Petitioners in No. 61, an association of open-end investment companies and several individual such companies, attack (1) portions of the Comptroller of the Currency's Regulation 9, purporting to authorize banks to operate collective investment funds, as violative of the Glass-Steagall Banking Act of 1933 and (2) the Comptroller's approval given First National City Bank to operate a collective investment fund. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Burlington Truck Lines, Inc. v. United States","cite":"371 U.S. 156","y":1962,"id":"1962/27","sc":1,"sum":"The judgment is reversed and the case is remanded to the District Court with instructions to set aside the Commission's order and remand the case to the Commission for further proceedings.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"usc","label":"16 U.S.C. § 825q","url":"https://www.law.cornell.edu/uscode/text/16/825q","op":1,"tname":"Conservation","by":{"0":"","1":""}},{"t":"usc","label":"15 U.S.C. § 79m","url":"https://www.law.cornell.edu/uscode/text/15/79m","subs":["(b)","(a)"],"stext":{"head":"§79m. Service, sales, and construction contracts","paras":[[0,"(a) Contracts by holding companies"],[0,"After April 1, 1936, it shall be unlawful for any registered holding company, by use of the mails or any means or instrumentality of interstate commerce, or otherwise, to enter into or take any step in the performance of any service, sales, or construction contract by which such company undertakes to perform services or construction work for, or sell goods to, any associate company thereof which is a public-utility or mutual service company. This provision shall not apply to such transactions, involving special or unusual circumstances or not in the ordinary course of business, as the Commission by rules and regulations or order may conditionally or unconditionally exempt as being necessary or appropriate in the public interest or for the protection of investors or consumers."],[0,"(b) Contracts by subsidiary or mutual service companies"],[0,"After April 1, 1936, it shall be unlawful for any subsidiary company of any registered holding company or for any mutual service company, by use of the mails or any means or instrumentality of interstate commerce, or otherwise, to enter into or take any step in the performance of any service, sales, or construction contract by which such company undertakes to perform services or construction work for, or sell goods to, any associate company thereof except in accordance with such terms and conditions and subject to such limitations and prohibitions as the Commission by rules and regulations or order shall prescribe as necessary or appropriate in the public interest or for the protection of investors or consumers and to insure that such contracts are performed economically and efficiently for the benefit of such associate companies at cost, fairly and equitably allocated among such companies. This provision shall not apply to such transactions as the Commission by rules and regulations or order may conditionally or unconditionally exempt as being necessary or appropriate in the public interest or for the protection of investors or consumers, if such transactions (1) are with any associate company which does not derive, directly or indirectly, any material part of its income from sources within the United States and which is not a public-utility company operating within the United States, or (2) involve special or unusual circumstances or are not in the ordinary course of business."],[0,"(c) Determination and allocation of costs; duration of contracts; regulation by rules of Commission"],[0,"The rules and regulations and orders of the Commission under this section may prescribe, among other things, such terms and conditions regarding the determination of costs and the allocation thereof among specified classes of companies and for specified classes of service, sales, and construction contracts, the duration of such contracts, the making and keeping of accounts and cost-accounting procedures, the filing of annual and other periodic and special reports, the maintenance of competitive conditions, the disclosure of interests, and similar matters, as the Commission deems necessary or appropriate in the public interest or for the protection of investors or consumers."],[0,"(d) Application for approval as mutual service company and nature of business; regulation by rules of Commission"],[0,"The rules and regulations and orders of the Commission under this section shall prescribe, among other things, such terms and conditions regarding the manner in which application may be made for approval as a mutual service company and the granting and continuance of such approval, the nature and enforcement of agreements for the sharing of expenses and distributing of revenues among member companies, and matters relating to such agreements, the nature and types of businesses and transactions in which mutual service companies may engage, and the manner of engaging therein, and the relations and transactions with member companies and affiliates, as the Commission deems necessary or appropriate in the public interest or for the protection of investors or consumers. The Commission shall not approve, or continue the approval of, any company as a mutual service company unless the Commission finds such company is so organized as to ownership, costs, revenues, and the sharing thereof as reasonably to insure the efficient and economical performance of service, sales, or construction contracts by such company for member companies, at cost fairly and equitably allocated among such member companies, at a reasonable saving to member companies over the cost to such companies of comparable contracts performed by independent persons. The Commission, upon its own motion or at the request of a member company or a State commission, may, after notice and opportunity for hearing, by order require a reallocation or reapportionment of costs among member companies of a mutual service company if it finds the existing allocation inequitable and may require the elimination of a service or services to a member company which does not bear its fair proportion of costs or which, by reason of its size or other circumstances, does not require such service or services. The Commission, after notice and opportunity for hearing, by order shall revoke, suspend, or modify the approval given any mutual service company if it finds that such company has persistently violated any provision of this section or any rule, regulation, or order thereunder."],[0,"(e) Contracts by affiliate in contravention of rules and regulations of Commission"],[0,"It shall be unlawful for any affiliate of any public-utility company engaged in interstate commerce, or of any registered holding company or subsidiary company thereof, by use of the mails or any means or instrumentality of interstate commerce, or otherwise, to enter into or take any step in the performance of any service, sales, or construction contract, by which such affiliate undertakes to perform services or construction work for, or sell goods to, any such company of which it is an affiliate, in contravention of such rules and regulations or orders regarding reports, accounts, costs, maintenance of competitive conditions, disclosure of interest, duration of contracts, and similar matters, as the Commission deems necessary or appropriate to prevent the circumvention of the provisions of this chapter or the rules, regulations, or orders thereunder."],[0,"(f) Contracts by persons engaged in performance of service, sales and construction in contravention of rules of Commission"],[0,"It shall be unlawful for any person whose principal business is the performance of service, sales, or construction contracts for public-utility or holding companies, by use of the mails or any means or instrumentality of interstate commerce, to enter into or take any step in the performance of any service, sales, or construction contract with any public-utility company, or for any such person, by use of the mails or any means or instrumentality of interstate commerce, or otherwise, to enter into or take any step in the performance of any service, sales, or construction contract with any public-utility company engaged in interstate commerce, or with any registered holding company or any subsidiary company of a registered holding company, in contravention of such rules and regulations or orders regarding reports, accounts, costs, maintenance of competitive conditions, disclosure of interest, duration of contracts, and similar matters as the Commission deems necessary or appropriate in the public interest or for the protection of investors or consumers or to prevent the circumvention of the provisions of this chapter or the rules, regulations, or orders thereunder."],[0,"(g) Investigations and recommendations by Commission"],[0,"The Commission, in order to obtain information to serve as a basis for recommending further legislation, shall from time to time conduct investigations regarding the making, performance, and costs of service, sales, and construction contracts with holding companies and subsidiary companies thereof and with public-utility companies, the economies resulting therefrom, and the desirability thereof. The Commission shall report to Congress, from time to time, the results of such investigations, together with such recommendations for legislation as it deems advisable. On the basis of such investigations the Commission shall classify the different types of such contracts and the work done thereunder, and shall make recommendations from time to time regarding the standards and scope of such contracts in relation to public-utility companies of different kinds and sizes and the costs incurred thereunder and economies resulting therefrom. Such recommendations shall be made available to State commissions, public-utility companies, and to the public in such form and at such reasonable charge as the Commission may prescribe."]],"more":false,"ed":"2004","src":"https://www.govinfo.gov/link/uscode/15/79m?type=usc&year=mostrecent&link-type=html"},"head":"§79m. Service, sales, and construction contracts","tname":"Commerce and Trade","by":{"0":"","1":""}},{"t":"usc","label":"15 U.S.C. § 79i","url":"https://www.law.cornell.edu/uscode/text/15/79i","stext":{"head":"§79i. Acquisition of securities and utility assets and other interests","paras":[[0,"(a) Acquisition prohibited prior to Commission approval"],[0,"Unless the acquisition has been approved by the Commission under section 79j of this title, it shall be unlawful—"],[1,"(1) for any registered holding company or any subsidiary company thereof, by use of the mails or any means or instrumentality of interstate commerce, or otherwise, to acquire, directly or indirectly, any securities or utility assets or any other interest in any business;"],[1,"(2) for any person, by use of the mails or any means or instrumentality of interstate commerce, to acquire, directly or indirectly, any security of any public-utility company, if such person is an affiliate under clause (A) of paragraph (11) of subsection (a) of section 79b of this title, of such company and of any other public utility or holding company, or will by virtue of such acquisition become such an affiliate."],[0,"(b) Acquisition of utility assets authorized by State Commission; holding company systems organized in same State"],[0,"Subsection (a) of this section shall not apply to—"],[1,"(1) the acquisition by a public-utility company of utility assets the acquisition of which has been expressly authorized by a State commission; or"],[1,"(2) the acquisition by a public-utility company of securities of a subsidiary public-utility company thereof, provided that both such public-utility companies and all other public-utility companies in the same holding-company system are organized in the same State, that the business of each such company in such system is substantially confined to such State, and that the acquisition of such securities has been expressly authorized by the State commission of such State."],[0,"(c) Acquisition of securities guaranteed by United States, State, or political subdivision; other securities and commercial paper held appropriate by Commission"],[0,"Subsection (a) of this section shall not apply to the acquisition by a registered holding company, or a subsidiary company thereof, of—"],[1,"(1) securities of, or securities the principal or interest of which is guaranteed by, the United States, a State, or political subdivision of a State, or any agency, authority, or instrumentality of any one or more of the foregoing, or any corporation which is wholly owned, directly or indirectly, by any one or more of the foregoing;"],[1,"(2) such other readily marketable securities within the limitation of such amounts, as the Commission may by rules and regulations prescribe as appropriate for investment of current funds and as not detrimental to the public interest or the interest of investors or consumers; or"],[1,"(3) such commercial paper and other securities, within such limitations, as the Commission may by rules and regulations or order prescribe as appropriate in the ordinary course of business of a registered holding company or subsidiary company thereof and as not detrimental to the public interest or the interest of investors or consumers."]],"more":false,"ed":"2004","src":"https://www.govinfo.gov/link/uscode/15/79i?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§79i. Acquisition of securities and utility assets and other interests","tname":"Commerce and Trade","by":{"0":"","1":""}},{"t":"usc","label":"16 U.S.C. § 824b","url":"https://www.law.cornell.edu/uscode/text/16/824b","stext":{"head":"§824b. Disposition of property; consolidations; purchase of securities","paras":[[0,"(a) Authorization"],[0,"(1) No public utility shall, without first having secured an order of the Commission authorizing it to do so—"],[1,"(A) sell, lease, or otherwise dispose of the whole of its facilities subject to the jurisdiction of the Commission, or any part thereof of a value in excess of $10,000,000;"],[1,"(B) merge or consolidate, directly or indirectly, its facilities subject to the jurisdiction of the Commission, or any part thereof, with the facilities of any other person, or any part thereof, that are subject to the jurisdiction of the Commission and have a value in excess of $10,000,000, by any means whatsoever;"],[1,"(C) purchase, acquire, or take any security with a value in excess of $10,000,000 of any other public utility; or"],[1,"(D) purchase, lease, or otherwise acquire an existing generation facility—"],[2,"(i) that has a value in excess of $10,000,000; and"],[2,"(ii) that is used for interstate wholesale sales and over which the Commission has jurisdiction for ratemaking purposes."],[0,"(2) No holding company in a holding company system that includes a transmitting utility or an electric utility shall purchase, acquire, or take any security with a value in excess of $10,000,000 of, or, by any means whatsoever, directly or indirectly, merge or consolidate with, a transmitting utility, an electric utility company, or a holding company in a holding company system that includes a transmitting utility, or an electric utility company, with a value in excess of $10,000,000 without first having secured an order of the Commission authorizing it to do so."],[0,"(3) Upon receipt of an application for such approval the Commission shall give reasonable notice in writing to the Governor and State commission of each of the States in which the physical property affected, or any part thereof, is situated, and to such other persons as it may deem advisable."],[0,"(4) After notice and opportunity for hearing, the Commission shall approve the proposed disposition, consolidation, acquisition, or change in control, if it finds that the proposed transaction will be consistent with the public interest, and will not result in cross-subsidization of a non-utility associate company or the pledge or encumbrance of utility assets for the benefit of an associate company, unless the Commission determines that the cross-subsidization, pledge, or encumbrance will be consistent with the public interest."],[0,"(5) The Commission shall, by rule, adopt procedures for the expeditious consideration of applications for the approval of dispositions, consolidations, or acquisitions, under this section. Such rules shall identify classes of transactions, or specify criteria for transactions, that normally meet the standards established in paragraph (4). The Commission shall provide expedited review for such transactions. The Commission shall grant or deny any other application for approval of a transaction not later than 180 days after the application is filed. If the Commission does not act within 180 days, such application shall be deemed granted unless the Commission finds, based on good cause, that further consideration is required to determine whether the proposed transaction meets the standards of paragraph (4) and issues an order tolling the time for acting on the application for not more than 180 days, at the end of which additional period the Commission shall grant or deny the application."],[0,"(6) For purposes of this subsection, the terms \"associate company\", \"holding company\", and \"holding company system\" have the meaning given those terms in the Public Utility Holding Company Act of 2005 [42 U.S.C. 16451 et seq.]."],[0,"(7)(A) Not later than 180 days after September 28, 2018, the Commission shall promulgate a rule requiring any public utility that is seeking to merge or consolidate, directly or indirectly, its facilities subject to the jurisdiction of the Commission, or any part thereof, with those of any other person, to notify the Commission of such transaction not later than 30 days after the date on which the transaction is consummated if—"],[1,"(i) the facilities, or any part thereof, to be acquired are of a value in excess of $1,000,000; and"],[1,"(ii) such public utility is not required to secure an order of the Commission under paragraph (1)(B)."],[0,"(B) In establishing any notification requirement under subparagraph (A), the Commission shall, to the maximum extent practicable, minimize the paperwork burden resulting from the collection of information."],[0,"(b) Orders of Commission"],[0,"The Commission may grant any application for an order under this section in whole or in part and upon such terms and conditions as it finds necessary or appropriate to secure the maintenance of adequate service and the coordination in the public interest of facilities subject to the jurisdiction of the Commission. The Commission may from time to time for good cause shown make such orders supplemental to any order made under this section as it may find necessary or appropriate."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/824b?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§824b. Disposition of property; consolidations; purchase of securities","tname":"Conservation","by":{"0":"","1":""}},{"t":"usc","label":"15 U.S.C. § 79t","url":"https://www.law.cornell.edu/uscode/text/15/79t","subs":["(b)"],"stext":{"head":"§79t. Rules, regulations, and orders","paras":[[0,"(a) Authority of Commission to make"],[0,"The Commission shall have authority from time to time to make, issue, amend, and rescind such rules and regulations and such orders as it may deem necessary or appropriate to carry out the provisions of this chapter, including rules and regulations defining accounting, technical, and trade terms used in this chapter. Among other things, the Commission shall have authority, for the purposes of this chapter, to prescribe the form or forms in which information required in any statement, declaration, application, report, or other document filed with the Commission shall be set forth, the items or details to be shown in balance sheets, profit and loss statements, and surplus accounts, the manner in which the cost of all assets, whenever determinable, shall be shown in regard to such statements, declarations, applications, reports, and other documents filed with the Commission, or accounts required to be kept by the rules, regulations, or orders of the Commission, and the methods to be followed in the keeping of accounts and cost-accounting procedures and the preparation of reports, in the segregation and allocation of costs, in the determination of liabilities, in the determination of depreciation and depletion, in the differentiation of recurring and nonrecurring income, in the differentiation of investment and operating income, and in the keeping or preparation, where the Commission deems it necessary or appropriate, of separate or consolidated balance sheets or profit and loss statements for any companies in the same holding-company system."],[0,"(b) Consistency with laws of United States or States"],[0,"In the case of the accounts of any company whose methods of accounting are prescribed under the provisions of any law of the United States or of any State, the rules and regulations or orders of the Commission in respect of accounts shall not be inconsistent with the requirements imposed by such law or any rule or regulation thereunder; nor shall anything in this chapter relieve any public-utility company from the duty to keep the accounts, books, records, or memoranda which may be required to be kept by the law of any State in which it operates or by the State Commission of any such State. But this provision shall not prevent the Commission from imposing such additional requirements regarding reports or accounts as it may deem necessary or appropriate in the public interest or for the protection of investors or consumers."],[0,"(c) Effective date; classification of persons and matters; hearings"],[0,"The rules and regulations of the Commission shall be effective upon publication in the manner which the Commission shall prescribe. For the purpose of its rules, regulations, or orders the Commission may classify persons and matters within its jurisdiction and prescribe different requirements for different classes of persons or matters. Orders of the Commission under this chapter shall be issued only after opportunity for hearing."],[0,"(d) Filing information or documents by reference"],[0,"The Commission, by such rules and regulations or order as it deems necessary or appropriate in the public interest or for the protection of investors or consumers, may authorize the filing of any information or documents required to be filed with the Commission under this chapter, or under the Securities Act of 1933, as amended [15 U.S.C. 77a et seq.], or under the Securities Exchange Act of 1934 [15 U.S.C. 78a et seq.], by incorporating by reference any information or documents theretofore or concurrently filed with the Commission under this chapter or either of such Acts. No provision of this chapter imposing any liability shall apply to any act done or omitted in good faith in conformity with any rule, regulation, or order of the Commission, notwithstanding that such rule, regulation, or order may, after such act or omission, be amended or rescinded or be determined by judicial or other authority to be invalid for any reason."]],"more":false,"ed":"2004","src":"https://www.govinfo.gov/link/uscode/15/79t?type=usc&year=mostrecent&link-type=html"},"head":"§79t. Rules, regulations, and orders","tname":"Commerce and Trade","by":{"0":"","1":""}},{"t":"case","label":"Gulf States Utilities Co. v. FPC","cite":"411 U.S. 747","y":1973,"id":"1972/71-1178","sc":1,"op":2,"sum":"Following petitioner's application under § 204 of the Federal Power Act to respondent Federal Power Commission (FPC) for authorization of a bond issue, two intervening cities opposed the authorization on the ground that the proceeds of the bond issue would be used to finance or refinance certain anticompetitive activities in violation of the antitrust laws, the Federal Power Act, and the Public Utility Holding …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Jersey Central Power & Light Co. v. FPC","cite":"319 U.S. 61","id":"scdb/1942-040","sc":1,"op":1,"sum":"1. The conclusion of the Federal Power Commission in this case that facilities owned and operated by a power company within a Statewhich connected with facilities of a second company, also within the State, whose facilities connected with those of a third company, in another State-were utilized for the transmission of electric energy across state lines, held supported by substantial evidence.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Chevron U.S.A. Inc. v. Natural Resources Defense Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"1":""}},{"t":"case","label":"Udall v. Tallman","cite":"380 U.S. 1","y":1965,"id":"1964/34","sc":1,"sum":"Since their promulgation, the Secretary of the Interior has consistently construed Executive Order No. 8979 and Public Land Order No. 487, relating to the disposition of public lands located in the Kenai National Moose Range in Alaska, not to bar the issuance of oil and gas leases. His interpretation has been made a repeated matter of public record, and a number of leases have been developed, at great expense, in …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Aluminum Co. of America v. Central Lincoln Peoples' Utility Dist.","cite":"467 U.S. 380","y":1984,"id":"1983/82-1071","sc":1,"op":1,"sum":"Since enactment of the Bonneville Project Act of 1937 (Project Act), the Bonneville Power Administration (BPA) has marketed low-cost hydroelectric power generated by a series of dams along the Columbia River. BPA sells two types of power: \"firm\" power (energy that BPA expects to produce under predictable streamflow conditions) and \"nonfirm\" power (energy that is in excess of firm power and is provided only when such …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"E.I. du Pont de Nemours & Co. v. Collins","cite":"432 U.S. 46","y":1977,"id":"1976/75-1870","sc":1,"sum":"In approving the merger of a closed-end investment company (Christiana), 98% of whose assets consisted of Du Pont & Co. common stock, into an affiliate company (Du Pont), the Securities and Exchange Commission (SEC) held to have reasonably exercised its discretion under § 17(b) of the Investment Company Act of 1940, as amended, in valuing Christiana essentially on the basis of the market value of Du Pont stock …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"United States v. National Ass'n of Securities Dealers, Inc.","cite":"422 U.S. 694","y":1975,"id":"1974/73-1701","sc":1,"sum":"Section 22 (d) of the Investment Company Act of 1940 provides that \"no dealer shall sell [mutual-fund shares] to any person except a dealer, a principal underwriter, or the issuer, except at a current public offering price described in the prospectus.\" Section 22 (f) authorizes mutual funds to impose restrictions on the negotiability and transferability of shares, provided they conform with the fund's registration …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Mississippi Power & Light Co. v. Mississippi","cite":"487 U.S. 354","y":1988,"id":"1987/86-1970","sc":1,"sum":"The FERC proceedings pre-empted a prudence inquiry by the MPSC. The decision in Nantahalarests on a foundation that is broad enough to support the order entered by FERC here and to require the MPSC to treat appellant's FERC-mandated payments for Grand Gulf costs as reasonably incurred operating expenses for the purpose of setting appellant's retail rates. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Dole v. United Steelworkers","cite":"110 S. Ct. 929","y":1990,"id":"1989/88-1434","sc":1,"sum":"The Act does not authorize OMB to review and countermand agency regulations mandating disclosure by regulated entities directly to third parties.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"City of New York v. FCC","cite":"486 U.S. 57","y":1988,"id":"1987/87-339","sc":1,"sum":"The FCC did not exceed its statutory authority by forbidding local authorities to impose technical cable signal quality standards more stringent than those set forth in the Commission's regulations.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"NLRB v. City Disposal Systems, Inc.","cite":"465 U.S. 822","id":"1983/82-960","sc":1,"sum":"Section 7 of the National Labor Relations Act provides that employees shall have the right to join or assist labor organizations, to bargain collectively, and \"to engage in other concerted activities for the purpose of collective bargaining or other mutual aid or protection.\" The collectivebargaining agreement between respondent and the union representing its truckdrivers provides that respondent shall not require …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Commodity Futures Trading Comm'n v. Schor","cite":"478 U.S. 833","y":1986,"id":"1985/85-621","sc":1,"sum":"Section 14 of the Commodity Exchange Act (CEA) provides that any person injured by a commodity broker's violation of the Act or regulations of the Commodity Futures Trading Commission (CFTC) may apply to the CFTC for an order directing the offender to pay reparations to the complainant and may enforce that order in federal district court. The CFTC promulgated a regulation that allows it in a reparations proceeding …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Chemical Manufacturers Ass'n v. Natural Resources Defense Council, Inc.","cite":"470 U.S. 116","y":1985,"id":"1984/83-1013","sc":1,"sum":"The view of the agency charged with administering the statute is entitled to considerable deference, and EPA's understanding of the statute is sufficiently rational to preclude a court from substituting its judgment for that of EPA.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Schneidewind v. ANR Pipeline Co.","cite":"108 S. Ct. 1145","y":1988,"id":"1987/86-986","sc":1,"sum":"The MPSC regulation of respondents through Act 144 impinges on a field that the federal regulatory scheme has occupied to the exclusion of state law, and Act 144 therefore is pre-empted.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Northwest Central Pipeline Corp. v. State Corp. Comm'n","cite":"109 S. Ct. 1262","y":1989,"id":"1988/86-1856","sc":1,"sum":"The issues for decision are whether a regulation adopted by appellee State Corporation Commission of Kansas (KCC) (1) was pre-empted by the federal Natural Gas Act (NGA) or (2) violates the Commerce Clause of the Constitution. Interrelated market, contractual, and regulatory factors have led interstate pipelines to cut back their purchases of \"old,\" federally regulated natural gas from producers at the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"SEC. In Appalachian Power Co. v. FPC","cite":"328 F.2d 237","url":"https://www.courtlistener.com/c/F.2d/328/237/","op":1,"by":{"1":""}},{"t":"case","label":"Public Util. Comm'n v. Attleboro Steam & Elec. Co.","cite":"273 U.S. 83","y":1927,"id":"scdb/1926-139","sc":1,"op":21,"sum":"Where a company engaged in the generation and sale of electricity in one State enters into a time contract with another company in an adjacent State, whereby current, to be paid for at an agreed rate, is delivered by the first to the second company at the state line and thence transmitted by the second company and sold to its customers in the second State, the transaction, and the transmission of the current, are …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"City of Lafayette v. SEC","cite":"454 F.2d 941","y":1971,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/454/941/","by":{"1":""}},{"t":"case","label":"North American Co. v. SEC","cite":"327 U.S. 686","id":"scdb/1945-064","sc":1,"sum":"1. The enactment of § 11 (b) (1) of the Public Utility Holding Company Act of 1935, authorizing the Securities and Exchange Commission to require each public utility holding company engaged in interstate commerce to limit its operations to a single integrated public utility system, was within the power of Congress under the commerce clause of the Constitution.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Attleboro. See Arkansas Electric Coop. Corp. v. Arkansas Pub. Serv. Comm'n","cite":"461 U.S. 375","y":1983,"id":"1982/81-731","sc":1,"sum":"Appellant is a customer-owned rural power cooperative established with loan funds and technical assistance provided by the federal Rural Electrification Administration (REA), but unlike most such cooperatives, which provide power directly to consumers, appellant's sole members and primary customers are 17 smaller Arkansas rural power cooperatives which in turn serve the ultimate consumer. Although tied into an …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"NLRB v. Curtin Matheson Scientific, Inc.","cite":"110 S. Ct. 1542","y":1990,"url":"https://www.courtlistener.com/c/S.%20Ct./110/1542/","sc":1,"by":{"1":""}},{"t":"case","label":"Delta Air Lines, Inc. v. August","cite":"450 U.S. 346","y":1981,"id":"1980/79-814","sc":1,"sum":"Federal Rule of Civil Procedure 68-which provides that if a plaintiff rejects a defendant's formal settlement offer \"to allow judgment to be taken against him,\" and if \"the judgment finally obtained by the offeree is not more favorable than the offer,\" the plaintiff \"must pay the costs incurred after the making of the offer\"-does not apply to a case in which judgment is entered against the plaintiff-offeree and in …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Adickes v. Kress & Co.","cite":"398 U.S. 144","id":"1969/79","sc":1,"sum":"Petitioner is a white school teacher who was refused service in respondent's lunchroom when she was accompanied by six Negro students, and who was arrested for vagrancy by the Hattiesburg, Mississippi, police when she left respondent's premises. She filed a complaint in the Federal District Court to recover damages alleging deprivation of her right under the Equal Protection Clause not to be discriminated against on …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"On Lee v. United States","cite":"343 U.S. 747","id":"scdb/1951-091","sc":1,"sum":"While petitioner was at large on bail pending his trial in a federal court on federal narcotics charges, an old acquaintance and former employee, who, unknown to petitioner, was a federal \"undercover agent\" and had a radio transmitter concealed on his person, entered the customer's room of petitioner's laundry and engaged petitioner in a conversation. Self-incriminating statements, made by petitioner during this …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Nantahala Power & Light Co. v. Thornburg","cite":"476 U.S. 953","y":1986,"id":"1985/85-568","sc":1,"op":1,"sum":"NCUC's allocation of entitlement and purchase power is pre-empted by federal law.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Mississippi Industries v. FERC","cite":"808 F.2d 1525","url":"https://www.courtlistener.com/c/F.2d/808/1525/","by":{"1":""}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"1":""}},{"t":"usc","label":"15 U.S.C. § 79","url":"https://www.law.cornell.edu/uscode/text/15/79","by":{"1":""}},{"t":"usc","label":"16 U.S.C. § 824","url":"https://www.law.cornell.edu/uscode/text/16/824","stext":{"head":"§824. Declaration of policy; application of subchapter","paras":[[0,"(a) Federal regulation of transmission and sale of electric energy"],[0,"It is declared that the business of transmitting and selling electric energy for ultimate distribution to the public is affected with a public interest, and that Federal regulation of matters relating to generation to the extent provided in this subchapter and subchapter III of this chapter and of that part of such business which consists of the transmission of electric energy in interstate commerce and the sale of such energy at wholesale in interstate commerce is necessary in the public interest, such Federal regulation, however, to extend only to those matters which are not subject to regulation by the States."],[0,"(b) Use or sale of electric energy in interstate commerce"],[0,"(1) The provisions of this subchapter shall apply to the transmission of electric energy in interstate commerce and to the sale of electric energy at wholesale in interstate commerce, but except as provided in paragraph (2) shall not apply to any other sale of electric energy or deprive a State or State commission of its lawful authority now exercised over the exportation of hydroelectric energy which is transmitted across a State line. The Commission shall have jurisdiction over all facilities for such transmission or sale of electric energy, but shall not have jurisdiction, except as specifically provided in this subchapter and subchapter III of this chapter, over facilities used for the generation of electric energy or over facilities used in local distribution or only for the transmission of electric energy in intrastate commerce, or over facilities for the transmission of electric energy consumed wholly by the transmitter."],[0,"(2) Notwithstanding subsection (f), the provisions of sections 824b(a)(2), 824e(e), 824i, 824j, 824j–1, 824k, 824o, 824o–1, 824p, 824q, 824r, 824s, 824t, 824u, and 824v of this title shall apply to the entities described in such provisions, and such entities shall be subject to the jurisdiction of the Commission for purposes of carrying out such provisions and for purposes of applying the enforcement authorities of this chapter with respect to such provisions. Compliance with any order or rule of the Commission under the provisions of section 824b(a)(2), 824e(e), 824i, 824j, 824j–1, 824k, 824o, 824o–1, 824p, 824q, 824r, 824s, 824t, 824u, or 824v of this title, shall not make an electric utility or other entity subject to the jurisdiction of the Commission for any purposes other than the purposes specified in the preceding sentence."],[0,"(c) Electric energy in interstate commerce"],[0,"For the purpose of this subchapter, electric energy shall be held to be transmitted in interstate commerce if transmitted from a State and consumed at any point outside thereof; but only insofar as such transmission takes place within the United States."],[0,"(d) \"Sale of electric energy at wholesale\" defined"],[0,"The term \"sale of electric energy at wholesale\" when used in this subchapter, means a sale of electric energy to any person for resale."],[0,"(e) \"Public utility\" defined"],[0,"The term \"public utility\" when used in this subchapter and subchapter III of this chapter means any person who owns or operates facilities subject to the jurisdiction of the Commission under this subchapter (other than facilities subject to such jurisdiction solely by reason of section 824e(e), 824e(f),1 824i, 824j, 824j–1, 824k, 824o, 824o–1, 824p, 824q, 824r, 824s, 824t, 824u, or 824v of this title)."],[0,"(f) United States, State, political subdivision of a State, or agency or instrumentality thereof exempt"],[0,"No provision in this subchapter shall apply to, or be deemed to include, the United States, a State or any political subdivision of a State, an electric cooperative that receives financing under the Rural Electrification Act of 1936 (7 U.S.C. 901 et seq.) or that sells less than 4,000,000 megawatt hours of electricity per year, or any agency, authority, or instrumentality of any one or more of the foregoing, or any corporation which is wholly owned, directly or indirectly, by any one or more of the foregoing, or any officer, agent, or employee of any of the foregoing acting as such in the course of his official duty, unless such provision makes specific reference thereto."],[0,"(g) Books and records"],[0,"(1) Upon written order of a State commission, a State commission may examine the books, accounts, memoranda, contracts, and records of—"],[1,"(A) an electric utility company subject to its regulatory authority under State law,"],[1,"(B) any exempt wholesale generator selling energy at wholesale to such electric utility, and"],[1,"(C) any electric utility company, or holding company thereof, which is an associate company or affiliate of an exempt wholesale generator which sells electric energy to an electric utility company referred to in subparagraph (A),"],[0,"wherever located, if such examination is required for the effective discharge of the State commission's regulatory responsibilities affecting the provision of electric service."],[0,"(2) Where a State commission issues an order pursuant to paragraph (1), the State commission shall not publicly disclose trade secrets or sensitive commercial information."],[0,"(3) Any United States district court located in the State in which the State commission referred to in paragraph (1) is located shall have jurisdiction to enforce compliance with this subsection."],[0,"(4) Nothing in this section shall—"],[1,"(A) preempt applicable State law concerning the provision of records and other information; or"],[1,"(B) in any way limit rights to obtain records and other information under Federal law, contracts, or otherwise."],[0,"(5) As used in this subsection the terms \"affiliate\", \"associate company\", \"electric utility company\", \"holding company\", \"subsidiary company\", and \"exempt wholesale generator\" shall have the same meaning as when used in the Public Utility Holding Company Act of 2005 [42 U.S.C. 16451 et seq.]."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/824?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§824. Declaration of policy; application of subchapter","tname":"Conservation","by":{"1":""}},{"t":"usc","label":"15 U.S.C. § 79a","url":"https://www.law.cornell.edu/uscode/text/15/79a","subs":["(b)"],"stext":{"head":"§79a. Necessity for control of holding companies","paras":[[0,"(a) Interstate nature of holding companies"],[0,"Public-utility holding companies and their subsidiary companies are affected with a national public interest in that, among other things, (1) their securities are widely marketed and distributed by means of the mails and instrumentalities of interstate commerce and are sold to a large number of investors in different States; (2) their service, sales, construction, and other contracts and arrangements are often made and performed by means of the mails and instrumentalities of interstate commerce; (3) their subsidiary public-utility companies often sell and transport gas and electric energy by the use of means and instrumentalities of interstate commerce; (4) their practices in respect of and control over subsidiary companies often materially affect the interstate commerce in which those companies engage; (5) their activities extending over many States are not susceptible of effective control by any State and make difficult, if not impossible, effective State regulation of public-utility companies."],[0,"(b) Protection of investors and interests of consumers"],[0,"Upon the basis of facts disclosed by the reports of the Federal Trade Commission made pursuant to S. Res. 83 (Seventieth Congress, first session), the reports of the Committee on Interstate and Foreign Commerce, House of Representatives, made pursuant to H. Res. 59 (Seventy-second Congress, first session) and H. J. Res. 572 (Seventy-second Congress, second session) and otherwise disclosed and ascertained, it is declared that the national public interest, the interest of investors in the securities of holding companies and their subsidiary companies and affiliates, and the interest of consumers of electric energy and natural and manufactured gas, are or may be adversely affected—"],[1,"(1) when such investors cannot obtain the information necessary to appraise the financial position or earning power of the issuers, because of the absence of uniform standard accounts; when such securities are issued without the approval or consent of the States having jurisdiction over subsidiary public-utility companies; when such securities are issued upon the basis of fictitious or unsound asset values having no fair relation to the sums invested in or the earning capacity of the properties and upon the basis of paper profits from intercompany transactions, or in anticipation of excessive revenues from subsidiary public-utility companies; when such securities are issued by a subsidiary public-utility company under circumstances which subject such company to the burden of supporting an overcapitalized structure and tend to prevent voluntary rate reductions;"],[1,"(2) when subsidiary public-utility companies are subjected to excessive charges for services, construction work, equipment, and materials, or enter into transactions in which evils result from an absence of arm's-length bargaining or from restraint of free and independent competition; when service, management, construction, and other contracts involve the allocation of charges among subsidiary public-utility companies in different States so as to present problems of regulation which cannot be dealt with effectively by the States;"],[1,"(3) when control of subsidiary public-utility companies affects the accounting practices and rate, dividend, and other policies of such companies so as to complicate and obstruct State regulation of such companies, or when control of such companies is exerted through disproportionately small investment;"],[1,"(4) when the growth and extension of holding companies bears no relation to economy of management and operation or the integration and coordination of related operating properties; or"],[1,"(5) when in any other respect there is lack of economy of management and operation of public-utility companies or lack of efficiency and adequacy of service rendered by such companies, or lack of effective public regulation, or lack of economies in the raising of capital."],[0,"(c) Declaration of policy of chapter"],[0,"When abuses of the character above enumerated become persistent and wide-spread the holding company becomes an agency which, unless regulated, is injurious to investors, consumers, and the general public; and it is declared to be the policy of this chapter, in accordance with which policy all the provisions of this chapter shall be interpreted, to meet the problems and eliminate the evils as enumerated in this section, connected with public-utility holding companies which are engaged in interstate commerce or in activities which directly affect or burden interstate commerce; and for the purpose of effectuating such policy to compel the simplification of public-utility holding-company systems and the elimination therefrom of properties detrimental to the proper functioning of such systems, and to provide as soon as practicable for the elimination of public-utility holding companies except as otherwise expressly provided in this chapter."]],"more":false,"ed":"2004","src":"https://www.govinfo.gov/link/uscode/15/79a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§79a. Necessity for control of holding companies","tname":"Commerce and Trade","by":{"1":""}},{"t":"usc","label":"15 U.S.C. § 79e","url":"https://www.law.cornell.edu/uscode/text/15/79e","by":{"1":""}},{"t":"usc","label":"15 U.S.C. § 79k","url":"https://www.law.cornell.edu/uscode/text/15/79k","by":{"1":""}},{"t":"usc","label":"15 U.S.C. § 79f","url":"https://www.law.cornell.edu/uscode/text/15/79f","stext":{"head":"§79f. Unlawful transactions by registered companies","paras":[[0,"(a) Issuing, selling, or altering rights of stockholders to declaration"],[0,"Except in accordance with a declaration effective under section 79g of this title and with the order under such section permitting such declaration to become effective, it shall be unlawful for any registered holding company or subsidiary company thereof, by use of the mails or any means or instrumentality of interstate commerce, or otherwise, directly or indirectly (1) to issue or sell any security of such company; or (2) to exercise any privilege or right to alter the priorities, preferences, voting power, or other rights of the holders of an outstanding security of such company."],[0,"(b) Exemptions from operation of subsection (a)"],[0,"The provisions of subsection (a) of this section shall not apply to the issue, renewal, or guaranty by a registered holding company or subsidiary company thereof of a note or draft (including the pledge of any security as collateral therefor) if such note or draft (1) is not part of a public offering, (2) matures or is renewed for not more than nine months, exclusive of days of grace, after the date of such issue, renewal, or guaranty thereof, and (3) aggregates (together with all other then outstanding notes and drafts of a maturity of nine months or less, exclusive of days of grace, as to which such company is primarily or secondarily liable) not more than 5 per centum of the principal amount and par value of the other securities of such company then outstanding, or such greater per centum thereof as the Commission upon application may by order authorize as necessary or appropriate in the public interest or for the protection of investors or consumers. In the case of securities having no principal amount or no par value, the value for the purposes of this subsection shall be the fair market value as of the date of issue. The Commission by rules and regulations or order, subject to such terms and conditions as it deems appropriate in the public interest or for the protection of investors or consumers, shall exempt from the provisions of subsection (a) of this section the issue or sale of any security by any subsidiary company of a registered holding company, if the issue and sale of such security are solely for the purpose of financing the business of such subsidiary company and have been expressly authorized by the State commission of the State in which such subsidiary company is organized and doing business, or if the issue and sale of such security are solely for the purpose of financing the business of such subsidiary company when such subsidiary company is not a holding company, a public-utility company, an investment company, or a fiscal or financing agency of a holding company, a public utility company, or an investment company. The provisions of subsection (a) of this section shall not apply to the issue, by a registered holding company or subsidiary company thereof, of a security issued pursuant to the terms of any security outstanding on January 1, 1935, giving the holder of such outstanding security the right to convert such outstanding security into another security of the same issuer or of another person, or giving the right to subscribe to another security of the same issuer or another issuer. Within ten days after any issue, sale, renewal, or guaranty exempted from the application of subsection (a) of this section by or under authority of this subsection, such holding company or subsidiary company thereof shall file with the Commission a certificate of notification in such form and setting forth such of the information required in a declaration under section 79g of this title as the Commission may by rules and regulations or order prescribe as necessary or appropriate in the public interest or for the protection of investors or consumers."],[0,"(c) Selling from house to house; causing officer or employer of subsidiary to sell"],[0,"It shall be unlawful, by use of the mails or any means or instrumentality of interstate commerce, or otherwise, for any registered holding company or any subsidiary company thereof, directly or indirectly—"],[1,"(1) to sell or offer for sale or to cause to be sold or offered for sale, from house to house, any security of such holding company; or"],[1,"(2) to cause any officer or employee of any subsidiary company of such holding company to sell or cause to be sold any security of such holding company."],[0,"As used in this subsection the term “house” shall not include an office used for business purposes."]],"more":false,"ed":"2004","src":"https://www.govinfo.gov/link/uscode/15/79f?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§79f. Unlawful transactions by registered companies","tname":"Commerce and Trade","by":{"1":""}},{"t":"usc","label":"15 U.S.C. § 79o","url":"https://www.law.cornell.edu/uscode/text/15/79o","stext":{"head":"§79o. Accounts and records","paras":[[0,"(a) Duty of holding companies to keep"],[0,"Every registered holding company and every subsidiary company thereof shall make, keep, and preserve for such periods, such accounts, cost-accounting procedures, correspondence, memoranda, papers, books, and other records as the Commission deems necessary or appropriate in the public interest or for the protection of investors or consumers or for the enforcement of the provisions of this chapter or the rules, regulations, or orders thereunder."],[0,"(b) Duty of affiliates to keep"],[0,"Every affiliate of a registered holding company or of any subsidiary company thereof, or of any public-utility company engaged in interstate commerce or not so engaged, shall make, keep, and preserve for such periods, such accounts, cost-accounting procedures, correspondence, memoranda, papers, books, and other records relating to any transaction of such affiliate which is subject to any provision of this chapter or any rule, regulation, or order thereunder, as the Commission deems necessary or appropriate in the public interest or for the protection of investors or consumers or for the enforcement of the provisions of this chapter or the rules, regulations, or orders thereunder."],[0,"(c) Duty of mutual service companies to keep"],[0,"Every mutual service company, and every affiliate of a mutual service company as to any transaction of such affiliate which is subject to any provision of this chapter or any rule, regulation, or order thereunder, shall make, keep, and preserve for such periods, such accounts, cost-accounting procedures, correspondence, memoranda, papers, books, and other records, as the Commission deems necessary or appropriate in the public interest or for the protection of investors or consumers or for the enforcement of the provisions of this chapter or the rules, regulations, or orders thereunder."],[0,"(d) Duty of persons engaged in service, sales, or construction to keep"],[0,"Every person whose principal business is the performance of service, sales, or construction contracts for public-utility or holding companies shall make, keep, and preserve for such periods, such accounts, cost-accounting procedures, correspondence, memoranda, papers, books, and other records, relating to any transaction by such person which is subject to any provision of this chapter or any rule, regulation, or order thereunder, as the Commission deems necessary or appropriate in the public interest or for the protection of investors or consumers or for the enforcement of the provisions of this chapter or the rules and regulations thereunder."],[0,"(e) Use of forms other than prescribed by Commission unlawful"],[0,"After the Commission has prescribed the form and manner of making and keeping accounts, cost-accounting procedures, correspondence, memoranda, papers, books, and other records to be kept by any person hereunder, it shall be unlawful for any such person to keep any accounts, cost-accounting procedures, correspondence, memoranda, papers, books, or other records other than those prescribed or such as may be approved by the Commission, or to keep his or its accounts, cost-accounting procedures, correspondence, memoranda, papers, books, or other records in any manner other than that prescribed or approved by the Commission."],[0,"(f) Examinations by Commission"],[0,"All accounts, cost-accounting procedures, correspondence, memoranda, papers, books, and other records kept or required to be kept by persons subject to any provision of this section shall be subject at any time and from time to time to such reasonable periodic, special, and other examinations by the Commission, or any member or representative thereof, as the Commission may prescribe. The Commission, after notice and opportunity for hearing, may prescribe the account or accounts in which particular outlays, receipts, and other transactions shall be entered, charged, or credited and the manner in which such entry, charge, or credit shall be made, and may require an entry to be modified or supplemented so as properly to show the cost of any asset or any other cost."],[0,"(g) Submission by holding company or subsidiary to examination by holders of securities"],[0,"It shall be the duty of every registered holding company and of every subsidiary company thereof and of every affiliate of a company insofar as such affiliate is subject to any provision of this chapter or any rule, regulation, or order thereunder, to submit the accounts, cost-accounting procedures, correspondence, memoranda, papers, books, and other records of such holding company, subsidiary company, or affiliate, as the case may be, to such examinations, in person or by duly appointed attorney, by the holder of any security of such holding company, subsidiary company, or affiliate, as the case may be, as the Commission deems necessary or appropriate in the public interest or for the protection of investors or consumers."],[0,"(h) Submission by mutual service companies and persons engaged in rendering service to examination by other companies"],[0,"It shall be the duty of every mutual service company, and of every affiliate of a mutual service company, and of every person whose principal business is the performance of service, sales, or construction contracts for public-utility or holding companies, insofar as such affiliate or such person is subject to any provision of this chapter or any rule, regulation, or order thereunder, to submit the accounts, cost-accounting procedures, correspondence, memoranda, papers, books, and other records of such mutual service company, affiliate, or person to such examinations, in person or by duly appointed attorney, by member companies of such mutual service company and by public-utility or holding companies for which such person performs service, sales, or construction contracts as the Commission deems necessary or appropriate in the public interest or for the protection of investors or consumers."],[0,"(i) Uniform methods for keeping accounts; power of Commission to prescribe"],[0,"The Commission, by such rules and regulations as it deems necessary or appropriate in the public interest or for the protection of investors or consumers may prescribe for persons subject to the provisions of subsections (a), (b), (c), or (d) of this section uniform methods for keeping accounts required under any provision of this section, including, among other things, the manner in which the cost of all assets, whenever determinable, shall be shown, the methods of classifying and segregating accounts, and the manner in which cost-accounting procedures shall be maintained."]],"more":false,"ed":"2004","src":"https://www.govinfo.gov/link/uscode/15/79o?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§79o. Accounts and records","tname":"Commerce and Trade","by":{"1":""}},{"t":"usc","label":"16 U.S.C. § 824d","url":"https://www.law.cornell.edu/uscode/text/16/824d","subs":["(e)"],"stext":{"head":"§824d. Rates and charges; schedules; suspension of new rates; automatic adjustment clauses","paras":[[0,"(a) Just and reasonable rates"],[0,"All rates and charges made, demanded, or received by any public utility for or in connection with the transmission or sale of electric energy subject to the jurisdiction of the Commission, and all rules and regulations affecting or pertaining to such rates or charges shall be just and reasonable, and any such rate or charge that is not just and reasonable is hereby declared to be unlawful."],[0,"(b) Preference or advantage unlawful"],[0,"No public utility shall, with respect to any transmission or sale subject to the jurisdiction of the Commission, (1) make or grant any undue preference or advantage to any person or subject any person to any undue prejudice or disadvantage, or (2) maintain any unreasonable difference in rates, charges, service, facilities, or in any other respect, either as between localities or as between classes of service."],[0,"(c) Schedules"],[0,"Under such rules and regulations as the Commission may prescribe, every public utility shall file with the Commission, within such time and in such form as the Commission may designate, and shall keep open in convenient form and place for public inspection schedules showing all rates and charges for any transmission or sale subject to the jurisdiction of the Commission, and the classifications, practices, and regulations affecting such rates and charges, together with all contracts which in any manner affect or relate to such rates, charges, classifications, and services."],[0,"(d) Notice required for rate changes"],[0,"Unless the Commission otherwise orders, no change shall be made by any public utility in any such rate, charge, classification, or service, or in any rule, regulation, or contract relating thereto, except after sixty days' notice to the Commission and to the public. Such notice shall be given by filing with the Commission and keeping open for public inspection new schedules stating plainly the change or changes to be made in the schedule or schedules then in force and the time when the change or changes will go into effect. The Commission, for good cause shown, may allow changes to take effect without requiring the sixty days' notice herein provided for by an order specifying the changes so to be made and the time when they shall take effect and the manner in which they shall be filed and published."],[0,"(e) Suspension of new rates; hearings; five-month period"],[0,"Whenever any such new schedule is filed the Commission shall have authority, either upon complaint or upon its own initiative without complaint, at once, and, if it so orders, without answer or formal pleading by the public utility, but upon reasonable notice, to enter upon a hearing concerning the lawfulness of such rate, charge, classification, or service; and, pending such hearing and the decision thereon, the Commission, upon filing with such schedules and delivering to the public utility affected thereby a statement in writing of its reasons for such suspension, may suspend the operation of such schedule and defer the use of such rate, charge, classification, or service, but not for a longer period than five months beyond the time when it would otherwise go into effect; and after full hearings, either completed before or after the rate, charge, classification, or service goes into effect, the Commission may make such orders with reference thereto as would be proper in a proceeding initiated after it had become effective. If the proceeding has not been concluded and an order made at the expiration of such five months, the proposed change of rate, charge, classification, or service shall go into effect at the end of such period, but in case of a proposed increased rate or charge, the Commission may by order require the interested public utility or public utilities to keep accurate account in detail of all amounts received by reason of such increase, specifying by whom and in whose behalf such amounts are paid, and upon completion of the hearing and decision may by further order require such public utility or public utilities to refund, with interest, to the persons in whose behalf such amounts were paid, such portion of such increased rates or charges as by its decision shall be found not justified. At any hearing involving a rate or charge sought to be increased, the burden of proof to show that the increased rate or charge is just and reasonable shall be upon the public utility, and the Commission shall give to the hearing and decision of such questions preference over other questions pending before it and decide the same as speedily as possible."],[0,"(f) Review of automatic adjustment clauses and public utility practices; action by Commission; \"automatic adjustment clause\" defined"],[0,"(1) Not later than 2 years after November 9, 1978, and not less often than every 4 years thereafter, the Commission shall make a thorough review of automatic adjustment clauses in public utility rate schedules to examine—"],[1,"(A) whether or not each such clause effectively provides incentives for efficient use of resources (including economical purchase and use of fuel and electric energy), and"],[1,"(B) whether any such clause reflects any costs other than costs which are—"],[2,"(i) subject to periodic fluctuations and"],[2,"(ii) not susceptible to precise determinations in rate cases prior to the time such costs are incurred."],[0,"Such review may take place in individual rate proceedings or in generic or other separate proceedings applicable to one or more utilities."],[0,"(2) Not less frequently than every 2 years, in rate proceedings or in generic or other separate proceedings, the Commission shall review, with respect to each public utility, practices under any automatic adjustment clauses of such utility to insure efficient use of resources (including economical purchase and use of fuel and electric energy) under such clauses."],[0,"(3) The Commission may, on its own motion or upon complaint, after an opportunity for an evidentiary hearing, order a public utility to—"],[1,"(A) modify the terms and provisions of any automatic adjustment clause, or"],[1,"(B) cease any practice in connection with the clause,"],[0,"if such clause or practice does not result in the economical purchase and use of fuel, electric energy, or other items, the cost of which is included in any rate schedule under an automatic adjustment clause."],[0,"(4) As used in this subsection, the term \"automatic adjustment clause\" means a provision of a rate schedule which provides for increases or decreases (or both), without prior hearing, in rates reflecting increases or decreases (or both) in costs incurred by an electric utility. Such term does not include any rate which takes effect subject to refund and subject to a later determination of the appropriate amount of such rate."],[0,"(g) Inaction of Commissioners"],[0,"(1) In general"],[1,"With respect to a change described in subsection (d), if the Commission permits the 60-day period established therein to expire without issuing an order accepting or denying the change because the Commissioners are divided two against two as to the lawfulness of the change, as a result of vacancy, incapacity, or recusal on the Commission, or if the Commission lacks a quorum—"],[2,"(A) the failure to issue an order accepting or denying the change by the Commission shall be considered to be an order issued by the Commission accepting the change for purposes of section 825l(a) of this title; and"],[2,"(B) each Commissioner shall add to the record of the Commission a written statement explaining the views of the Commissioner with respect to the change."],[0,"(2) Appeal"],[1,"If, pursuant to this subsection, a person seeks a rehearing under section 825l(a) of this title, and the Commission fails to act on the merits of the rehearing request by the date that is 30 days after the date of the rehearing request because the Commissioners are divided two against two, as a result of vacancy, incapacity, or recusal on the Commission, or if the Commission lacks a quorum, such person may appeal under section 825l(b) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/824d?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§824d. Rates and charges; schedules; suspension of new rates; automatic adjustment clauses","tname":"Conservation","by":{"1":""}},{"t":"usc","label":"16 U.S.C. § 824c","url":"https://www.law.cornell.edu/uscode/text/16/824c","stext":{"head":"§824c. Issuance of securities; assumption of liabilities","paras":[[0,"(a) Authorization by Commission"],[0,"No public utility shall issue any security, or assume any obligation or liability as guarantor, indorser, surety, or otherwise in respect of any security of another person, unless and until, and then only to the extent that, upon application by the public utility, the Commission by order authorizes such issue or assumption of liability. The Commission shall make such order only if it finds that such issue or assumption (a) is for some lawful object, within the corporate purposes of the applicant and compatible with the public interest, which is necessary or appropriate for or consistent with the proper performance by the applicant of service as a public utility and which will not impair its ability to perform that service, and (b) is reasonably necessary or appropriate for such purposes. The provisions of this section shall be effective six months after August 26, 1935."],[0,"(b) Application approval or modification; supplemental orders"],[0,"The Commission, after opportunity for hearing, may grant any application under this section in whole or in part, and with such modifications and upon such terms and conditions as it may find necessary or appropriate, and may from time to time, after opportunity for hearing and for good cause shown, make such supplemental orders in the premises as it may find necessary or appropriate, and may by any such supplemental order modify the provisions of any previous order as to the particular purposes, uses, and extent to which, or the conditions under which, any security so theretofore authorized or the proceeds thereof may be applied, subject always to the requirements of subsection (a) of this section."],[0,"(c) Compliance with order of Commission"],[0,"No public utility shall, without the consent of the Commission, apply any security or any proceeds thereof to any purpose not specified in the Commission's order, or supplemental order, or to any purpose in excess of the amount allowed for such purpose in such order, or otherwise in contravention of such order."],[0,"(d) Authorization of capitalization not to exceed amount paid"],[0,"The Commission shall not authorize the capitalization of the right to be a corporation or of any franchise, permit, or contract for consolidation, merger, or lease in excess of the amount (exclusive of any tax or annual charge) actually paid as the consideration for such right, franchise, permit, or contract."],[0,"(e) Notes or drafts maturing less than one year after issuance"],[0,"Subsection (a) shall not apply to the issue or renewal of, or assumption of liability on, a note or draft maturing not more than one year after the date of such issue, renewal, or assumption of liability, and aggregating (together with all other then outstanding notes and drafts of a maturity of one year or less on which such public utility is primarily or secondarily liable) not more than 5 per centum of the par value of the other securities of the public utility then outstanding. In the case of securities having no par value, the par value for the purpose of this subsection shall be the fair market value as of the date of issue. Within ten days after any such issue, renewal, or assumption of liability, the public utility shall file with the Commission a certificate of notification, in such form as may be prescribed by the Commission, setting forth such matters as the Commission shall by regulation require."],[0,"(f) Public utility securities regulated by State not affected"],[0,"The provisions of this section shall not extend to a public utility organized and operating in a State under the laws of which its security issues are regulated by a State commission."],[0,"(g) Guarantee or obligation on part of United States"],[0,"Nothing in this section shall be construed to imply any guarantee or obligation on the part of the United States in respect of any securities to which the provisions of this section relate."],[0,"(h) Filing duplicate reports with the Securities and Exchange Commission"],[0,"Any public utility whose security issues are approved by the Commission under this section may file with the Securities and Exchange Commission duplicate copies of reports filed with the Federal Power Commission in lieu of the reports, information, and documents required under sections 77g, 78l, and 78m of title 15."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/824c?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§824c. Issuance of securities; assumption of liabilities","tname":"Conservation","by":{"1":""}},{"t":"usc","label":"16 U.S.C. § 825","url":"https://www.law.cornell.edu/uscode/text/16/825","stext":{"head":"§825. Accounts and records","paras":[[0,"(a) Duty to keep"],[0,"Every licensee and public utility shall make, keep, and preserve for such periods, such accounts, records of cost-accounting procedures, correspondence, memoranda, papers, books, and other records as the Commission may by rules and regulations prescribe as necessary or appropriate for purposes of the administration of this chapter, including accounts, records, and memoranda of the generation, transmission, distribution, delivery, or sale of electric energy, the furnishing of services or facilities in connection therewith, and receipts and expenditures with respect to any of the foregoing: Provided, however, That nothing in this chapter shall relieve any public utility from keeping any accounts, memoranda, or records which such public utility may be required to keep by or under authority of the laws of any State. The Commission may prescribe a system of accounts to be kept by licensees and public utilities and may classify such licensees and public utilities and prescribe a system of accounts for each class. The Commission, after notice and opportunity for hearing, may determine by order the accounts in which particular outlays and receipts shall be entered, charged, or credited. The burden of proof to justify every accounting entry questioned by the Commission shall be on the person making, authorizing, or requiring such entry, and the Commission may suspend a charge or credit pending submission of satisfactory proof in support thereof."],[0,"(b) Access to and examination by the Commission"],[0,"The Commission shall at all times have access to and the right to inspect and examine all accounts, records, and memoranda of licensees and public utilities, and it shall be the duty of such licensees and public utilities to furnish to the Commission, within such reasonable time as the Commission may order, any information with respect thereto which the Commission may by order require, including copies of maps, contracts, reports of engineers, and other data, records, and papers, and to grant to all agents of the Commission free access to its property and its accounts, records, and memoranda when requested so to do. No member, officer, or employee of the Commission shall divulge any fact or information which may come to his knowledge during the course of examination of books or other accounts, as hereinbefore provided, except insofar as he may be directed by the Commission or by a court."],[0,"(c) Controlling individual"],[0,"The books, accounts, memoranda, and records of any person who controls, directly or indirectly, a licensee or public utility subject to the jurisdiction of the Commission, and of any other company controlled by such person, insofar as they relate to transactions with or the business of such licensee or public utility, shall be subject to examination on the order of the Commission."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/825?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§825. Accounts and records","tname":"Conservation","by":{"1":""}},{"t":"usc","label":"15 U.S.C. § 79u","url":"https://www.law.cornell.edu/uscode/text/15/79u","by":{"1":""}},{"t":"usc","label":"16 U.S.C. § 824a","url":"https://www.law.cornell.edu/uscode/text/16/824a","subs":["(a)"],"by":{"1":""}},{"t":"usc","label":"15 U.S.C. § 825","url":"https://www.law.cornell.edu/uscode/text/15/825","by":{"1":""}},{"t":"usc","label":"15 U.S.C. § 79j","url":"https://www.law.cornell.edu/uscode/text/15/79j","subs":["(b)(1)"],"stext":{"head":"§79j. Approval of acquisition of securities and utility assets and other interests","paras":[[0,"(a) Contents of application"],[0,"A person may apply for approval of the acquisition of securities or utility assets, or of any other interest in any business, by filing an application in such form as the Commission may by rules and regulations prescribe as necessary or appropriate in the public interest or for the protection of investors and consumers. Such application shall include—"],[1,"(1) in the case of the acquisition of securities, such information and copies of such documents as the Commission may by rules and regulations or order prescribe as necessary or appropriate in the public interest or for the protection of investors or consumers in respect of—"],[2,"(A) the security to be acquired, the consideration to be paid therefor, and compliance with such State laws as may apply in respect of the issue, sale, or acquisition thereof,"],[2,"(B) the outstanding securities of the company whose security is to be acquired, the terms, position, rights, and privileges of each class and the options in respect of any such securities,"],[2,"(C) the names of all security holders of record (or otherwise known to the applicant) owning, holding, or controlling 1 per centum or more of any class of security of such company, the officers and directors of such company, and their remuneration, security holdings in, material contracts with, and borrowings from such company and the offices or directorships held, and securities owned, held, or controlled, by them in other companies,"],[2,"(D) the bonus, profit-sharing and voting-trust agreements, underwriting arrangements, trust indentures, mortgages, and similar documents, by whatever name known, of or relating to such company,"],[2,"(E) the material contracts, not made in the ordinary course of business, and the service, sales, and construction contracts of such company,"],[2,"(F) the securities owned, held, or controlled, directly or indirectly, by such company,"],[2,"(G) balance sheets and profit and loss statements of such company for not more than the five preceding fiscal years, certified, if required by the rules and regulations of the Commission by an independent public accountant,"],[2,"(H) any further information regarding such company and any associate company or affiliate thereof or its relations with the applicant company, and"],[2,"(I) if the applicant be not a registered holding company, any of the information and documents which may be required under section 79e of this title from a registered holding company;"],[1,"(2) in the case of the acquisition of utility assets, such information concerning such assets, the value thereof and consideration to be paid therefor, the owner or owners thereof and their relation to, agreements with, and interest in the securities of, the applicant or any associate company thereof as the Commission may by rules and regulations or order prescribe as necessary or appropriate in the public interest or for the protection of investors or consumers; and"],[1,"(3) in the case of the acquisition of any other interest in any business, such information concerning such business and the interest to be acquired, and the consideration to be paid, as the Commission may by rules and regulations or order prescribe as necessary or appropriate in the public interest or for the protection of investors or consumers."],[0,"(b) Conditions affecting approval"],[0,"If the requirements of subsection (f) of this section are satisfied, the Commission shall approve the acquisition unless the Commission finds that—"],[1,"(1) such acquisition will tend towards interlocking relations or the concentration of control of public-utility companies, of a kind or to an extent detrimental to the public interest or the interest of investors or consumers;"],[1,"(2) in case of the acquisition of securities or utility assets, the consideration, including all fees, commissions, and other remuneration, to whomsoever paid, to be given, directly or indirectly, in connection with such acquisition is not reasonable or does not bear a fair relation to the sums invested in or the earning capacity of the utility assets to be acquired or the utility assets underlying the securities to be acquired; or"],[1,"(3) such acquisition will unduly complicate the capital structure of the holding-company system of the applicant or will be detrimental to the public interest or the interest of investors or consumers or the proper functioning of such holding-company system."],[0,"The Commission may condition its approval of the acquisition of securities of another company upon such a fair offer to purchase such of the other securities of the company whose security is to be acquired as the Commission may find necessary or appropriate in the public interest or for the protection of investors or consumers."],[0,"(c) Conditions barring approval"],[0,"Notwithstanding the provisions of subsection (b) of this section, the Commission shall not approve—"],[1,"(1) an acquisition of securities or utility assets, or of any other interest, which is unlawful under the provisions of section 79h of this title or is detrimental to the carrying out of the provisions of section 79k of this title; or"],[1,"(2) the acquisition of securities or utility assets of a public-utility or holding company unless the Commission finds that such acquisition will serve the public interest by tending towards the economical and efficient development of an integrated public-utility system. This paragraph shall not apply to the acquisition of securities or utility assets of a public-utility company operating exclusively outside the United States."],[0,"(d) Approval to be granted in reasonable time"],[0,"Within such reasonable time after the filing of an application under this section as the Commission shall fix by rules and regulations or order, the Commission shall enter an order either granting or, after notice and opportunity for hearing, denying approval of the acquisition unless the applicant shall withdraw its application. Amendments to an application may be made upon such terms and conditions as the Commission may prescribe."],[0,"(e) Terms and conditions of order granting approval"],[0,"The Commission, in any order approving the acquisition of securities or utility assets, may prescribe such terms and conditions in respect of such acquisition, including the price to be paid for such securities or utility assets, as the Commission may find necessary or appropriate in the public interest or for the protection of investors or consumers."],[0,"(f) Compliance with State laws as condition of approval"],[0,"The Commission shall not approve any acquisition as to which an application is made under this section unless it appears to the satisfaction of the Commission that such State laws as may apply in respect of such acquisition have been complied with, except where the Commission finds that compliance with such State laws would be detrimental to the carrying out of the provisions of section 79k of this title."]],"more":false,"ed":"2004","src":"https://www.govinfo.gov/link/uscode/15/79j?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§79j. Approval of acquisition of securities and utility assets and other interests","tname":"Commerce and Trade","by":{"1":""}}]};